/* Experience-only roadmap: one entrance, SVG energy flow, lightweight parallax. */
(()=>{
 const root=document.querySelector('#experiences'),wrap=root.querySelector('.journey-wrap'),svg=root.querySelector('.journey-road'),cards=[...root.querySelectorAll('.journey-card')],first=root.querySelector('.journey-pin-2025'),last=root.querySelector('.journey-pin-2026'),flag=root.querySelector('.journey-flag'),reduced=matchMedia('(prefers-reduced-motion:reduce)'),mobile=matchMedia('(max-width:700px)'),fine=matchMedia('(hover:hover) and (pointer:fine)');
 const main=root.querySelector('#journey-road-path'),lit=[...svg.querySelectorAll('.journey-road-shadow,.journey-road-lit,.journey-road-core')],near=svg.querySelector('.road-near'),far=svg.querySelector('.road-far'),desktop=main.getAttribute('d'),desktopNear=near.getAttribute('d'),desktopFar=far.getAttribute('d');let entered=false,visible=false,frame=0,pointer=null,timers=[];
 function layout(){if(!mobile.matches){svg.setAttribute('viewBox','0 0 1000 1000');lit.forEach(p=>p.setAttribute('d',desktop));near.setAttribute('d',desktopNear);far.setAttribute('d',desktopFar);[first,last,flag].forEach(el=>{el.style.removeProperty('left');el.style.removeProperty('top')});return}
  const width=wrap.clientWidth,height=wrap.offsetHeight,timeline=root.querySelector('.journey-milestones'),sx=mobile.matches&&width<350?30:38,sy=timeline.offsetTop+cards[0].offsetTop+25,ey=timeline.offsetTop+cards[1].offsetTop+25,mid=(sy+ey)/2,fy=timeline.offsetTop+cards[1].offsetTop+cards[1].offsetHeight+85;const low=`M ${sx} ${sy} C ${sx-20} ${sy+100} ${sx+22} ${mid-70} ${sx} ${mid}`,high=`M ${sx} ${mid} C ${sx-20} ${mid+70} ${sx+22} ${ey-90} ${sx} ${ey} C ${sx-8} ${ey+95} ${sx+8} ${fy-55} ${sx} ${fy}`,full=low+` C ${sx-20} ${mid+70} ${sx+22} ${ey-90} ${sx} ${ey} C ${sx-8} ${ey+95} ${sx+8} ${fy-55} ${sx} ${fy}`;svg.setAttribute('viewBox',`0 0 ${width} ${height}`);lit.forEach(p=>p.setAttribute('d',full));near.setAttribute('d',low);far.setAttribute('d',high);first.style.left=last.style.left=flag.style.left=`${sx}px`;first.style.top=`${sy}px`;last.style.top=`${ey}px`;flag.style.top=`${fy-56}px`;
 }
 new ResizeObserver(layout).observe(wrap);cards.forEach(card=>new ResizeObserver(layout).observe(card));mobile.addEventListener('change',layout);layout();
 function pause(){root.classList.toggle('journey-paused',document.hidden||!visible);if(document.hidden||!visible||reduced.matches)svg.pauseAnimations?.();else svg.unpauseAnimations?.()}
 function complete(){timers.forEach(clearTimeout);timers=[];root.classList.add('journey-entered','journey-start-visible','journey-drawing','journey-arrived','journey-ready')}
 function enter(){if(entered)return;entered=true;root.classList.add('journey-entered');if(reduced.matches){complete();return}timers.push(setTimeout(()=>root.classList.add('journey-start-visible'),400));timers.push(setTimeout(()=>{root.classList.add('journey-drawing');root.querySelector('#journey-reveal-motion').beginElement?.()},800));timers.push(setTimeout(()=>root.classList.add('journey-arrived'),2800));timers.push(setTimeout(()=>root.classList.add('journey-ready'),3500))}
 new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)enter();pause()},{threshold:.08}).observe(root);document.addEventListener('visibilitychange',pause);reduced.addEventListener('change',()=>{if(reduced.matches&&entered)complete();pause()});
 function point(){frame=0;if(!pointer||reduced.matches||!visible)return;const r=root.getBoundingClientRect(),x=(pointer.clientX-r.left)/r.width-.5,y=(pointer.clientY-r.top)/r.height-.5;root.style.setProperty('--terrain-x',`${x*2}px`);root.style.setProperty('--terrain-y',`${y*1.5}px`);root.style.setProperty('--rock-x',`${x*8}px`);root.style.setProperty('--rock-y',`${y*5}px`);root.style.setProperty('--card-x',`${x*1.5}px`);root.style.setProperty('--card-y',`${y}px`)}if(fine.matches){root.addEventListener('pointermove',e=>{pointer=e;if(!frame)frame=requestAnimationFrame(point)},{passive:true});root.addEventListener('pointerleave',()=>{pointer=null;['--terrain-x','--terrain-y','--rock-x','--rock-y','--card-x','--card-y'].forEach(key=>root.style.removeProperty(key))})}
})();
